\title{The Unreasonable Effectiveness of Wrong Theories:\\ A Perturbative Geometry of Theory-Space}
\author{Aristotle}
\date{2026-07-11}

\begin{document}
\begin{abstract}
We develop a rigorous geometric framework in which physical theories are points of a real inner-product space, the truth is a distinguished point, and the \emph{wrongness} of a theory is its distance to the truth. Within this framework we prove a meta-theorem answering, in precise mathematical terms, why approximately correct theories are so effective---and why theories known to be wrong nevertheless remain indispensable. We establish (i) a perturbative convergence theory in which corrections summing to the truth-gap drive wrongness to zero, with an explicit tail bound and, under geometric decay of corrections, an explicit exponential rate $M r^{n}/(1-r)$; (ii) a non-degeneracy principle characterizing the truth as the unique theory perfect on all phenomena; and (iii) the central meta-theorem: whenever two theories fail in non-parallel directions, there is a phenomenon on which the ``wrong'' theory predicts the truth exactly while its rival errs, so a globally worse theory can strictly out-predict a globally better one locally. All results hold over an arbitrary real inner-product space.
\end{abstract}

\maketitle

\section{Introduction}
The history of physics is a history of superseded theories, yet each superseded theory was, and often still is, extraordinarily useful. This tension---global falsity coexisting with local, sometimes exact, predictive success---is usually discussed philosophically. We give it a mathematical treatment.

Our thesis is that once ``theories,'' ``truth,'' ``phenomena,'' and ``wrongness'' are modeled geometrically, the effectiveness of wrong theories ceases to be mysterious and becomes a theorem about inner-product spaces. Theory-space is a real inner-product space $E$; each theory is a point; the truth is a fixed point $\tau \in E$; wrongness is Euclidean distance to truth; phenomena are directions $u \in E$, a theory's prediction is the linear functional $\ip{T}{u}$, and its prediction error is $|\ip{T-\tau}{u}|$.

\section{The geometry of theory-space}
Throughout, $E$ is a real vector space. For the metric results we require only a norm; for the phenomenological results we require a real inner product $\ip{\cdot}{\cdot}$ with induced norm $\|v\|=\sqrt{\ip{v}{v}}$.

\begin{definition}[Theory, truth, wrongness]
A \emph{theory} is a point $T \in E$. A distinguished point $\tau \in E$ is the \emph{truth}. The \emph{wrongness} of $T$ is $w(T) := \|T-\tau\|$.
\end{definition}

\begin{definition}[Phenomenon, prediction, prediction error]
A \emph{phenomenon} is a vector $u \in E$ (a measurement direction). The \emph{prediction} of $T$ on $u$ is $\ip{T}{u}$, and the \emph{prediction error} is $\err(T,u) := |\ip{T-\tau}{u}|$.
\end{definition}

\begin{proposition}[Basic properties]
For all $T$: $w(T)\ge 0$ and $w(\tau)=0$.
\end{proposition}
\begin{proof}
Immediate from $w(T)=\|T-\tau\|$ and the norm axioms.
\end{proof}

\begin{definition}[Perturbative sequence]
Given a base theory $T_0 \in E$ and corrections $c:\N\to E$, the $n$-th \emph{partial theory} is $T_n := T_0 + \sum_{i=0}^{n-1} c_i$. In particular $T_0$ is the base theory.
\end{definition}

\section{Perturbative convergence theory}
This section uses only the normed-space structure of $E$. We never require $E$ to be finite-dimensional; completeness is invoked only when summing infinite correction series. In the finite-dimensional case one may picture $E=\R^d$ with the usual dot product, and every statement below specializes to elementary linear algebra.

\begin{theorem}[Lipschitz stability of wrongness]
For any theory $T$ and correction $c$, $\;|w(T+c)-w(T)| \le \|c\|.$
\end{theorem}
\begin{proof}
$w(T+c)-w(T)=\|T+c-\tau\|-\|T-\tau\|$. The reverse triangle inequality $|\,\|x\|-\|y\|\,|\le\|x-y\|$ with $x=T+c-\tau$, $y=T-\tau$ gives the bound since $x-y=c$.
\end{proof}

\begin{lemma}[Exactness criterion]
$w(T)=0$ if and only if $T=\tau$.
\end{lemma}
\begin{proof}
$\|T-\tau\|=0 \iff T-\tau=0 \iff T=\tau$.
\end{proof}

\begin{theorem}[Convergence to truth]
If the series $\sum_i c_i$ converges to $\tau-T_0$, then $w(T_n)\to 0$ as $n\to\infty$.
\end{theorem}
\begin{proof}
If $\sum_{i<n}c_i\to\tau-T_0$ then $T_n=T_0+\sum_{i<n}c_i\to\tau$ by continuity of addition; composing with the continuous norm gives $w(T_n)=\|T_n-\tau\|\to 0$.
\end{proof}

\begin{theorem}[Perturbative tail bound]
Suppose $E$ is complete and $\sum_i\|c_i\|<\infty$. With $\tau=T_0+\sum_i c_i$,
\[ w(T_n) \le \sum_{i=0}^{\infty}\|c_{i+n}\|. \]
\end{theorem}
\begin{proof}
Absolute summability implies summability, so $\sum_i c_i$ exists and splits as $\sum_{i<n}c_i+\sum_i c_{i+n}$. Hence $T_n-\tau=\sum_{i<n}c_i-\sum_i c_i=-\sum_i c_{i+n}$, and $w(T_n)=\|\sum_i c_{i+n}\|\le\sum_i\|c_{i+n}\|$ by the triangle inequality for infinite sums.
\end{proof}

\begin{theorem}[Vanishing of the tail bound]
For any correction sequence $c$, $\;\sum_{i=0}^{\infty}\|c_{i+n}\|\to 0$ as $n\to\infty$.
\end{theorem}
\begin{proof}
The tails of a convergent nonnegative series vanish as the starting index increases.
\end{proof}

\begin{theorem}[Explicit exponential rate]
Suppose $E$ is complete and $\|c_i\|\le M r^{i}$ for all $i$, with $M\ge 0$ and $0\le r<1$. With $\tau=T_0+\sum_i c_i$,
\[ w(T_n) \le \frac{M\,r^{n}}{1-r}. \]
\end{theorem}
\begin{proof}
Geometric decay makes $\sum_i\|c_i\|$ summable, so the tail bound applies: $w(T_n)\le\sum_i\|c_{i+n}\|\le\sum_i M r^{i+n}=M r^{n}\sum_i r^{i}=M r^{n}/(1-r)$, using $\sum_{i\ge0}r^i=1/(1-r)$.
\end{proof}

\section{The phenomenological layer and the meta-theorem}
We now use the inner product.

\begin{lemma}[Exactness on orthogonal phenomena]
If $\ip{T-\tau}{u}=0$ then $\err(T,u)=0$: $T$ predicts $u$ exactly, however wrong $T$ is overall.
\end{lemma}
\begin{proof}
$\err(T,u)=|\ip{T-\tau}{u}|=|0|=0$.
\end{proof}

\begin{theorem}[Non-degeneracy: truth is characterized by phenomena]
$T=\tau$ if and only if $\ip{T-\tau}{u}=0$ for every $u\in E$.
\end{theorem}
\begin{proof}
($\Rightarrow$) If $T=\tau$ then $T-\tau=0$ and all inner products vanish. ($\Leftarrow$) Take $u=T-\tau$; then $\ip{T-\tau}{T-\tau}=0$, so positive-definiteness gives $T-\tau=0$.
\end{proof}

\begin{theorem}[The exact-prediction hyperplane]
For $T\ne\tau$, the set of phenomena on which $T$ is exactly right equals $(T-\tau)^{\perp}$, a closed hyperplane of codimension one; when $\dim E\ge 2$ this set is infinite.
\end{theorem}
\begin{proof}
$\err(T,u)=0\iff\ip{T-\tau}{u}=0\iff u\in(T-\tau)^\perp$; since $T-\tau\ne0$ this is a hyperplane.
\end{proof}

\begin{theorem}[Meta-theorem: a wrong theory out-predicts a non-parallel rival]
Let $A$ and $B$ be theories and $\tau$ the truth. Assume $A\ne\tau$ and $B-\tau\ne r(A-\tau)$ for every $r\in\R$. Then there exists a phenomenon $u$ with
\[ \err(A,u)=0 < \err(B,u). \]
\end{theorem}
\begin{proof}
Write $a=A-\tau$, $b=B-\tau$; then $\ip{a}{a}>0$. Set $t=\ip{b}{a}/\ip{a}{a}$ and $u=b-ta$. Then $\ip{u}{a}=\ip{b}{a}-t\ip{a}{a}=0$, so by the orthogonality lemma $\err(A,u)=|\ip{a}{u}|=0$. Non-parallelism forces $u\ne0$ (else $b=ta$), so $\|u\|^2>0$; and $\ip{b}{u}=\ip{u+ta}{u}=\ip{u}{u}+t\ip{a}{u}=\|u\|^2>0$, giving $\err(B,u)=\|u\|^2>0$.
\end{proof}

\begin{remark}
Globally, $w(A)\ge w(B)$ is possible: $B$ may be nearer the truth. The theorem isolates a phenomenon aligned with the part of $B$'s error that $A$'s error cannot account for. Locality of measurement, not global superiority, lets a wrong theory win.
\end{remark}

\begin{remark}[Necessity of non-parallelism]
The non-parallelism hypothesis cannot be dropped. If $B-\tau=r(A-\tau)$ then both theories fail in the same direction, every phenomenon on which $A$ is exactly right lies in $(A-\tau)^\perp$ where $B$ is also exactly right, and no separating phenomenon exists. But in dimension $d\ge2$ the vectors parallel to a fixed one form a single line---a measure-zero exception---so generically the errors are non-parallel.
\end{remark}

\begin{theorem}[Mutual domination]
If $A\ne\tau$, $B\ne\tau$, and the errors of $A$ and $B$ are non-parallel, then there is a phenomenon on which $A$ out-predicts $B$ and a phenomenon on which $B$ out-predicts $A$: neither wrong theory is uniformly better.
\end{theorem}
\begin{proof}
Apply the previous theorem twice, swapping the roles of $A$ and $B$; non-parallelism is symmetric.
\end{proof}

\section{Algorithms}
\textbf{Algorithm A (Winning phenomenon).} Given $a=A-\tau\ne0$ and $b=B-\tau$ non-parallel to $a$, compute $t=\ip{b}{a}/\ip{a}{a}$ and return $u=b-ta$; then $\err(A,u)=0$ and $\err(B,u)=\|u\|^2>0$. Cost $O(d)$ in dimension $d$.

\smallskip
\noindent\textbf{Algorithm B (Certified perturbative refinement).} Iterate $T_{n+1}=T_n+c_n$ while reporting the certificate $M r^{n}/(1-r)$; stop when it drops below $\varepsilon$, i.e. after $n\ge\log(\varepsilon(1-r)/M)/\log r$ steps.

\section{Applications and discussion}
The framework formalizes why superseded theories persist: each governs the hyperplane orthogonal to its error and can out-predict differently-miscalibrated rivals there. Theorem~3.6 abstracts convergence-rate estimates for perturbation series and iterative solvers, while the tail bound yields a computable stopping criterion. The results split into a diachronic half (convergence and rates) and a synchronic half (non-degeneracy and the meta-theorem), unified by the error vector $T-\tau$: its magnitude is wrongness, its direction fixes the exact-prediction hyperplane, and the relation between two error vectors decides which theory wins a phenomenon.

\section{Future work}
Variable convergence ratios $\|c_{i+1}\|\le r_i\|c_i\|$ with product-form bounds; a dimension theory of exact-prediction sets; a best-rival max--min refinement over finite families; a measure-theoretic $L^2$ analogue with weighted error $\int|\ip{T-\tau}{u}|^2\,d\mu(u)$; and operator/dynamical theory-spaces.

\section{Conclusion}
Treating theories as points, truth as a target, and phenomena as directions turns a philosophical puzzle into geometry. Wrongness converges---often exponentially---under perturbative correction; truth is exactly the theory perfect on all phenomena; and every wrong theory, failing in its own direction, commands a hyperplane of phenomena on which it is exactly right and can strictly out-predict a rival. The effectiveness of wrong theories is the geometry of error.

